update sc_plans set spec = coalesce(spec,'{}'::jsonb) || $j${"bible": {"grandpa": "GRANDPA: a thin Korean grandpa in his late seventies, short white hair, kind wrinkled face, faded olive-green padded jacket, grey wool trousers, no hat. ", "scarf": "SCARF: a long hand-knitted cherry-red wool scarf with one small cream-white felt heart patch sewn near one end. ", "place": "PLACE: a small Seoul neighborhood bus stop: a plain wooden bench under a simple glass shelter with no signs or route numbers, a big ginkgo tree right beside it, a round twig magpie nest on a low ginkgo branch at shoulder height. ", "cart": "CART: a small two-wheeled hand cart stacked with plain brown flattened cardboard boxes. ", "young_magpies": "three young magpies slightly smaller than Kachi, plain black-and-white, no neckerchief, no satchel", "palette": "cut 1 = last winter: cooler blue-grey tones with a soft vignette; cuts 2-3 = this winter: warm amber streetlamp light, falling snow, golden ginkgo leaves under the snow"}, "shots": [{"n": 1, "img_prompt": "GRANDPA: a thin Korean grandpa in his late seventies, short white hair, kind wrinkled face, faded olive-green padded jacket, grey wool trousers, no hat. SCARF: a long hand-knitted cherry-red wool scarf with one small cream-white felt heart patch sewn near one end. PLACE: a small Seoul neighborhood bus stop: a plain wooden bench under a simple glass shelter with no signs or route numbers, a big ginkgo tree right beside it, a round twig magpie nest on a low ginkgo branch at shoulder height. Last winter, at night, snow falling, cooler blue-grey tones with a soft vignette. The grandpa stands beside the ginkgo tree in profile and gently tucks the red scarf into the nest, covering three tiny fluffy grey magpie chicks; the heart patch on the scarf is large and clearly visible at the front of the nest. His hands are hidden under the scarf. Kachi sits on the same branch a little to the side, watching him with soft eyes. The magpie is exactly the character in the magpie reference image: a small round chibi magpie with a glossy black head, cream-white face and belly, big shiny dark-brown eyes, short black beak, dark navy-blue wings, a red knotted neckerchief and a small brown leather satchel. It does NOT hold a microphone. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/c1_magpie.jpeg"], "reuse": null, "action": "The grandpa slowly lowers the end of the red scarf over the chicks; the chicks snuggle in; snow drifts down. Keep the miniature clay diorama look and every character design identical to the first frame. One simple, small action only; subtle, slow, gentle motion; the camera stays almost still with at most a slow gentle push-in. No text, no morphing faces, no extra fingers or limbs, no sudden camera shake, no cuts.", "dur": 5, "cap": "Last winter, he gave away his only scarf.", "detail": "heart patch (front of nest, centre)"}, {"n": 2, "img_prompt": "GRANDPA: a thin Korean grandpa in his late seventies, short white hair, kind wrinkled face, faded olive-green padded jacket, grey wool trousers, no hat. SCARF: a long hand-knitted cherry-red wool scarf with one small cream-white felt heart patch sewn near one end. PLACE: a small Seoul neighborhood bus stop: a plain wooden bench under a simple glass shelter with no signs or route numbers, a big ginkgo tree right beside it, a round twig magpie nest on a low ginkgo branch at shoulder height. CART: a small two-wheeled hand cart stacked with plain brown flattened cardboard boxes. This winter, early evening, the first snow, warm amber streetlamp light, golden ginkgo leaves under the snow. The grandpa, wearing NO scarf, sits on the snowy bench next to the cart, his reddened bare hands tucked under his arms, shoulders hunched from the cold. On the bench beside him, Kachi has just landed holding the end of the long red scarf in its beak; the rest of the scarf trails behind Kachi across the snowy bench, the heart patch visible on the scarf. The grandpa looks down at Kachi in surprise. The magpie is exactly the character in the magpie reference image: a small round chibi magpie with a glossy black head, cream-white face and belly, big shiny dark-brown eyes, short black beak, dark navy-blue wings, a red knotted neckerchief and a small brown leather satchel. It does NOT hold a microphone. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/c1_magpie.jpeg", "<cut1 image>"], "reuse": null, "action": "Kachi takes one small hop toward the grandpa, pulling the scarf end onto his knee; snowflakes fall slowly. Keep the miniature clay diorama look and every character design identical to the first frame. One simple, small action only; subtle, slow, gentle motion; the camera stays almost still with at most a slow gentle push-in. No text, no morphing faces, no extra fingers or limbs, no sudden camera shake, no cuts.", "dur": 5, "cap": "This winter, someone remembered.", "detail": "bare reddened hands, no scarf; heart patch on the trailing scarf"}, {"n": 3, "img_prompt": "GRANDPA: a thin Korean grandpa in his late seventies, short white hair, kind wrinkled face, faded olive-green padded jacket, grey wool trousers, no hat. SCARF: a long hand-knitted cherry-red wool scarf with one small cream-white felt heart patch sewn near one end. PLACE: a small Seoul neighborhood bus stop: a plain wooden bench under a simple glass shelter with no signs or route numbers, a big ginkgo tree right beside it, a round twig magpie nest on a low ginkgo branch at shoulder height. This winter, evening, gentle falling snow, warm amber streetlamp light. The grandpa sits on the bench with the red scarf now wrapped warmly around his neck, the heart patch resting on his chest; teary eyes and a soft trembling smile, his hands hidden in the scarf. Kachi sits beside him on the bench looking up at him. Far behind and above, on top of the glass shelter roof, three young magpies slightly smaller than Kachi, plain black-and-white, no neckerchief, no satchel sit in a neat row as small simple silhouettes looking down. The magpie is exactly the character in the magpie reference image: a small round chibi magpie with a glossy black head, cream-white face and belly, big shiny dark-brown eyes, short black beak, dark navy-blue wings, a red knotted neckerchief and a small brown leather satchel. It does NOT hold a microphone. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/c1_magpie.jpeg", "<cut2 image>"], "reuse": null, "action": "The grandpa slowly touches the heart patch under his chin and smiles through a tear; snow falls gently. Keep the miniature clay diorama look and every character design identical to the first frame. One simple, small action only; subtle, slow, gentle motion; the camera stays almost still with at most a slow gentle push-in. No text, no morphing faces, no extra fingers or limbs, no sudden camera shake, no cuts.", "dur": 5, "cap": "Some kindness flies back home.", "detail": "heart patch on his chest; three grown young magpies on the shelter roof"}], "details": [{"prop": "목도리 끝 하트 헝겊", "where": [1, 2, 3], "meaning": "그 목도리가 바로 할아버지 것 — 알아보는 순간이 반전"}, {"prop": "맨손·목도리 없는 목 ↔ 두른 목도리", "where": [2, 3], "meaning": "추위 → 온기"}, {"prop": "정류장 지붕 위 다 자란 새끼 셋", "where": [3], "meaning": "그가 살린 가족이 1년 뒤 그를 지켜본다"}], "est_usd": 1.13, "notes": "16:40 결정 반영: 5컷→3컷(약 14초+엔딩). 컷2에 '목도리 없는 할아버지'와 '까치가 목도리를 끌어옴'을 합쳤다. 새 그림 3장(목도리 위치가 컷마다 달라 마지막 프레임 이어 쓰기 불가) → 약 $1.13. 위험: 컷3 지붕 위 새 셋은 작은 실루엣으로만. 글자·노선번호 없음.", "score": {"surprise": 4, "emotion": 5, "natural": 4, "kachi": 5}}$j$::jsonb, outline = $j$[{"scene": "heart patch (front of nest, centre)", "cap": "Last winter, he gave away his only scarf.", "action": "The grandpa slowly lowers the end of the red scarf over the chicks; the chicks snuggle in; snow drifts down."}, {"scene": "bare reddened hands, no scarf; heart patch on the trailing scarf", "cap": "This winter, someone remembered.", "action": "Kachi takes one small hop toward the grandpa, pulling the scarf end onto his knee; snowflakes fall slowly."}, {"scene": "heart patch on his chest; three grown young magpies on the shelter roof", "cap": "Some kindness flies back home.", "action": "The grandpa slowly touches the heart patch under his chin and smiles through a tear; snow falls gently."}]$j$::jsonb, feedback = coalesce(feedback,'[]'::jsonb) || $j$[{"at": "2026-10-28T08:50:00Z", "by": "claude", "type": "note", "text": "촬영표 완성(PLAN-FIRST): 3컷, 예상 $1.13. 점수 놀라움4·감정5·자연4·까치5. 16:40 결정 반영: 5컷→3컷(약 14초+엔딩). 컷2에 '목도리 없는 할아버지'와 '까치가 목도리를 끌어옴'을 합쳤다. 새 그림 3장(목도리 위치가 컷마다 달라 마지막 프레임 이어 쓰기 불가) → 약 $1.13. 위험: 컷3 지붕 위 새 셋은 작은 실루엣으로만. 글자·노선번호 없음"}]$j$::jsonb, updated_at=now() where id='P261028-bus-scarf';
update sc_plans set spec = coalesce(spec,'{}'::jsonb) || $j${"bible": {"guard": "GUARD: a gentle Korean apartment night guard in his sixties, grey hair under a navy-blue flat cap, round kind face, navy-blue padded uniform jacket with no badge or text, ", "booth": "BOOTH: a tiny wooden guard booth with a frosty window, a round wall clock with no numbers, a small brown radio, warm lamp light inside, snowy apartment garden outside", "cats": "a tabby mother cat with four small tabby kittens", "blanket": "his own brown-and-cream plaid wool blanket", "box": "a white foam box with a round doorway cut in one side", "palette": "cold blue night outside, warm amber lamp light inside; dawn = soft peach light"}, "shots": [{"n": 1, "img_prompt": "(existing) social/side/gen/gc1_cold.jpeg", "refs": [], "reuse": "gcv1_cold.mp4", "action": "(existing video)", "dur": 5, "cap": "The first cold night.", "detail": "mother cat and kittens shivering under the frosty shrub"}, {"n": 2, "img_prompt": "(existing) social/side/gen/gc3_box.jpeg", "refs": [], "reuse": "gcv3_box.mp4", "action": "(existing video)", "dur": 5, "cap": "He gave them his own blanket.", "detail": "plaid blanket folded next to the foam box (front right)"}, {"n": 3, "img_prompt": "(existing) social/side/gen/gc4_kachi.jpeg", "refs": [], "reuse": "gcv4_kachi.mp4", "action": "(existing video)", "dur": 5, "cap": "Kachi brought one more.", "detail": "Kachi drops the red scarf into the box"}, {"n": 4, "img_prompt": "GUARD: a gentle Korean apartment night guard in his sixties, grey hair under a navy-blue flat cap, round kind face, navy-blue padded uniform jacket with no badge or text, dozing peacefully in his wooden chair inside the tiny guard booth at dawn, head tilted, a calm smile. BOOTH: a tiny wooden guard booth with a frosty window, a round wall clock with no numbers, a small brown radio, warm lamp light inside, snowy apartment garden outside. Draped over his knees is his own brown-and-cream plaid wool blanket, and curled asleep on his lap on top of the blanket is the tabby mother cat with her four small kittens tucked against her belly, mostly hidden in the blanket folds. Soft peach dawn light through the frosty window, the empty white foam box with the round doorway visible outside the open booth door in the snow. Only the guard and the cats, no other characters. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/gc3_box.jpeg", "social/side/gen/gc2_window.jpeg", "social/side/gen/gc62_dawn.jpeg"], "reuse": null, "action": "The guard breathes slowly in his sleep; the mother cat's ear twitches once; dawn light brightens softly. Keep the miniature clay diorama look and every character design identical to the first frame. One simple, small action only; subtle, slow, gentle motion; the camera stays almost still with at most a slow gentle push-in. No text, no morphing faces, no extra fingers or limbs, no sudden camera shake, no cuts.", "dur": 5, "cap": "That night, they kept him warm.", "detail": "same plaid blanket now on his knees, cats on his lap, empty box outside"}], "details": [{"prop": "경비 아저씨의 체크무늬 담요", "where": [2, 4], "meaning": "자기 담요를 내어 줬다 → 새벽엔 그 담요 위에서 고양이들이 그를 데운다"}, {"prop": "새벽 빈 상자", "where": [4], "meaning": "고양이들이 따뜻한 상자를 두고 그에게 왔다 = 반전"}, {"prop": "까치의 빨간 목도리", "where": [3], "meaning": "까치도 자기 것을 보탰다"}], "est_usd": 0.38, "notes": "P0에 맞춰 새로 짬: 기존 영상 3컷(gcv1·gcv3·gcv4) 재사용 + 새 반전 컷 1개(그림 1+영상 1 ≈ $0.38). 반전: 자기 담요를 내어 준 아저씨를, 새벽엔 고양이 가족이 그 담요 위에서 데워 준다. 컷4는 인물 2종(아저씨·고양이), 까치 없음 → 까치 ref 넣지 않음. 4컷 ≈ 18초+엔딩.", "score": {"surprise": 4, "emotion": 4, "natural": 4, "kachi": 4}, "description": "The first cold night in Seoul. A night guard gave a stray cat family his own blanket. By dawn, they gave him something back.\n\nIn Korea, the magpie is the bird that brings good news 🐦\n\n#Kindness #StrayCat #Kittens #Seoul #Korea #shorts", "format": "kindness-returns", "reuse": ["social/side/gen/gcv1_cold.mp4", "social/side/gen/gcv3_box.mp4", "social/side/gen/gcv4_kachi.mp4"]}$j$::jsonb, outline = $j$[{"scene": "mother cat and kittens shivering under the frosty shrub", "cap": "The first cold night.", "action": "(existing video)"}, {"scene": "plaid blanket folded next to the foam box (front right)", "cap": "He gave them his own blanket.", "action": "(existing video)"}, {"scene": "Kachi drops the red scarf into the box", "cap": "Kachi brought one more.", "action": "(existing video)"}, {"scene": "same plaid blanket now on his knees, cats on his lap, empty box outside", "cap": "That night, they kept him warm.", "action": "The guard breathes slowly in his sleep; the mother cat's ear twitches once; dawn light brightens softly."}]$j$::jsonb, feedback = coalesce(feedback,'[]'::jsonb) || $j$[{"at": "2026-10-28T08:50:00Z", "by": "claude", "type": "note", "text": "촬영표 완성(PLAN-FIRST): 4컷, 예상 $0.38. 점수 놀라움4·감정4·자연4·까치4. P0에 맞춰 새로 짬: 기존 영상 3컷(gcv1·gcv3·gcv4) 재사용 + 새 반전 컷 1개(그림 1+영상 1 ≈ $0.38). 반전: 자기 담요를 내어 준 아저씨를, 새벽엔 고양이 가족이 그 담요 위에서 데워 준다. 컷4는 인물 2종(아저씨·고양이), 까치 없음 → 까치 ref 넣"}]$j$::jsonb, updated_at=now(), title = $j$He gave the stray cats his blanket 🥹$j$, title_ko = $j$고양이에게 담요를 내어 준 경비 아저씨$j$, hook = $j$첫 프레임: 서리 낀 화단 밑에서 떠는 엄마 고양이와 새끼 넷$j$ where id='P261101-guard-cat-house';
update sc_plans set spec = coalesce(spec,'{}'::jsonb) || $j${"bible": {"mom1998": "young Korean mother, black hair in a low bun dusted with snow, brown wool coat, dark grey scarf, worn grey gloves", "son1998": "small boy in a sage-green knitted hat and green padded jacket", "now": "grown son in a navy coat and grey scarf; mother now white-haired in a plum wool coat", "place": "snowy winter market night, bungeoppang stall with a red cloth awning, a hanging bulb, cast-iron fish moulds, golden fish-shaped bread", "palette": "cool snowy blue night with warm bulb light"}, "shots": [{"n": 1, "img_prompt": "(existing) social/side/gen/mh2_give.jpeg", "refs": [], "reuse": "mhv2_give.mp4", "action": "(existing video)", "dur": 5, "cap": "Winter, 1998. \"I'm not hungry.\"", "detail": "one paper bag only, handed to the boy"}, {"n": 2, "img_prompt": "(existing) social/side/gen/mh3_watch.jpeg", "refs": [], "reuse": null, "action": "The boy chews happily; the mother watches him and quietly swallows, smiling; Kachi on the awning tilts its head; snow falls softly. Keep the miniature clay diorama look and every character design identical to the first frame. One simple, small action only; subtle, slow, gentle motion; the camera stays almost still with at most a slow gentle push-in. No text, no morphing faces, no extra fingers or limbs, no sudden camera shake, no cuts.", "dur": 5, "cap": "She was. Kachi saw it.", "detail": "mom's empty hands; Kachi on the awning watching"}, {"n": 3, "img_prompt": "(existing) social/side/gen/mh62_bite.jpeg", "refs": [], "reuse": null, "action": "The white-haired mother takes a small bite and laughs with teary eyes; Kachi slowly nudges the heart parcel toward her. Keep the miniature clay diorama look and every character design identical to the first frame. One simple, small action only; subtle, slow, gentle motion; the camera stays almost still with at most a slow gentle push-in. No text, no morphing faces, no extra fingers or limbs, no sudden camera shake, no cuts.", "dur": 5, "cap": "Years later... \"You first, Mom.\"", "detail": "same stall; Kachi delivers a heart parcel"}], "details": [{"prop": "같은 붕어빵 노점(빨간 천 지붕)", "where": [1, 2, 3], "meaning": "세월이 흘러 같은 자리에서 갚는다"}, {"prop": "1998년 봉투는 아이 손에만", "where": [1, 2], "meaning": "엄마는 먹지 않았다"}, {"prop": "그때도 지금도 지붕 위·옆의 까치", "where": [2, 3], "meaning": "까치는 그날을 기억하고 좋은 소식을 들고 온다"}], "est_usd": 0.5, "notes": "3컷으로 압축, 이미 만든 그림·영상 재사용(새 영상 2개 ≈ $0.50). 까치 역할: 1998년에 엄마가 굶는 걸 본 까치가 세월 뒤 같은 노점에 하트 소포를 가져온다.", "score": {"surprise": 4, "emotion": 5, "natural": 4, "kachi": 4}, "format": "mom-sacrifice-repaid", "reuse": ["social/side/gen/mhv2_give.mp4", "social/side/gen/mh3_watch.jpeg", "social/side/gen/mh62_bite.jpeg"]}$j$::jsonb, outline = $j$[{"scene": "one paper bag only, handed to the boy", "cap": "Winter, 1998. \"I'm not hungry.\"", "action": "(existing video)"}, {"scene": "mom's empty hands; Kachi on the awning watching", "cap": "She was. Kachi saw it.", "action": "The boy chews happily; the mother watches him and quietly swallows, smiling; Kachi on the awning tilts its head; snow falls softly."}, {"scene": "same stall; Kachi delivers a heart parcel", "cap": "Years later... \"You first, Mom.\"", "action": "The white-haired mother takes a small bite and laughs with teary eyes; Kachi slowly nudges the heart parcel toward her."}]$j$::jsonb, feedback = coalesce(feedback,'[]'::jsonb) || $j$[{"at": "2026-10-28T08:50:00Z", "by": "claude", "type": "note", "text": "촬영표 완성(PLAN-FIRST): 3컷, 예상 $0.5. 점수 놀라움4·감정5·자연4·까치4. 3컷으로 압축, 이미 만든 그림·영상 재사용(새 영상 2개 ≈ $0.50). 까치 역할: 1998년에 엄마가 굶는 걸 본 까치가 세월 뒤 같은 노점에 하트 소포를 가져온다."}]$j$::jsonb, updated_at=now() where id='P261031-mom-not-hungry';
update sc_plans set spec = coalesce(spec,'{}'::jsonb) || $j${"bible": {"grandma": "GRANDMA: a small elderly Korean grandmother, white hair in a low bun, round kind wrinkled face, quilted plum-purple vest over a cream blouse, long grey skirt (same face as the grandmother in the grandma reference image). ", "gate": "GATE: a hanok wooden double gate under a small tiled roof, a stone wall, a warm paper lantern glowing beside the gate, an old persimmon tree with a few orange persimmons behind the wall, a small round wooden bird-feeder dish full of grain fixed on top of the wall. ", "ghost": "GHOST: a tiny trick-or-treater exactly the size of the magpie, completely covered by a small white cloth sheet with two round eye holes, two little black-and-navy tail feathers peeking out under the hem, holding a tiny felt pumpkin basket with a cute smiling face. ", "bowl": "an empty brass bowl", "palette": "Halloween night, deep blue sky, warm lantern light, autumn leaves"}, "shots": [{"n": 1, "img_prompt": "GATE: a hanok wooden double gate under a small tiled roof, a stone wall, a warm paper lantern glowing beside the gate, an old persimmon tree with a few orange persimmons behind the wall, a small round wooden bird-feeder dish full of grain fixed on top of the wall. GHOST: a tiny trick-or-treater exactly the size of the magpie, completely covered by a small white cloth sheet with two round eye holes, two little black-and-navy tail feathers peeking out under the hem, holding a tiny felt pumpkin basket with a cute smiling face. GRANDMA: a small elderly Korean grandmother, white hair in a low bun, round kind wrinkled face, quilted plum-purple vest over a cream blouse, long grey skirt (same face as the grandmother in the grandma reference image). Halloween night. The gate is half open; the grandma stands in the doorway holding an empty brass bowl, looking down in surprise at the tiny ghost waiting on the stone step in front of her. The tail feathers under the sheet and the grain dish on the wall are clearly visible. No other characters. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/kb2_point.jpeg"], "reuse": null, "action": "The tiny ghost gives one small hop on the step and lifts its pumpkin basket; the grandma's face softens into a smile. Keep the miniature clay diorama look and every character design identical to the first frame. One simple, small action only; subtle, slow, gentle motion; the camera stays almost still with at most a slow gentle push-in. No text, no morphing faces, no extra fingers or limbs, no sudden camera shake, no cuts.", "dur": 5, "cap": "A tiny ghost. And no candy left.", "detail": "empty bowl; black tail feathers under the sheet; grain dish on the wall"}, {"n": 2, "img_prompt": "GATE: a hanok wooden double gate under a small tiled roof, a stone wall, a warm paper lantern glowing beside the gate, an old persimmon tree with a few orange persimmons behind the wall, a small round wooden bird-feeder dish full of grain fixed on top of the wall. GRANDMA: a small elderly Korean grandmother, white hair in a low bun, round kind wrinkled face, quilted plum-purple vest over a cream blouse, long grey skirt (same face as the grandmother in the grandma reference image). Same Halloween night at the gate. The grandma kneels on the step, smiling and laughing in surprise. The white cloth sheet has slipped off and lies on the step: under it is Kachi, holding out to her a small heart-patterned parcel tied with red string; the tiny felt pumpkin basket beside Kachi now holds one dried persimmon. The magpie is exactly the character in the magpie reference image: a small round chibi magpie with a glossy black head, cream-white face and belly, big shiny dark-brown eyes, short black beak, dark navy-blue wings, a red knotted neckerchief and a small brown leather satchel. It does NOT hold a microphone. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/kb2_point.jpeg", "social/side/gen/c1_magpie.jpeg", "<cut1 image>"], "reuse": null, "action": "Kachi slowly pushes the heart parcel toward the grandma; she laughs softly. Keep the miniature clay diorama look and every character design identical to the first frame. One simple, small action only; subtle, slow, gentle motion; the camera stays almost still with at most a slow gentle push-in. No text, no morphing faces, no extra fingers or limbs, no sudden camera shake, no cuts.", "dur": 5, "cap": "It came to give, not to take.", "detail": "sheet on the step, dried persimmon in the basket"}, {"n": 3, "img_prompt": "GRANDMA: a small elderly Korean grandmother, white hair in a low bun, round kind wrinkled face, quilted plum-purple vest over a cream blouse, long grey skirt (same face as the grandmother in the grandma reference image). Same Halloween night, warm lantern light, sitting on the wooden step of the hanok gate. The grandma has opened the small parcel and holds up a child's crayon drawing on plain paper: a grandma and a little child holding hands under a persimmon tree, surrounded by drawn hearts, no writing at all. Her eyes are teary, a big soft smile. Kachi sits on her knee looking up at her. The magpie is exactly the character in the magpie reference image: a small round chibi magpie with a glossy black head, cream-white face and belly, big shiny dark-brown eyes, short black beak, dark navy-blue wings, a red knotted neckerchief and a small brown leather satchel. It does NOT hold a microphone. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/kb2_point.jpeg", "social/side/gen/c1_magpie.jpeg", "<cut2 image>"], "reuse": null, "action": "The grandma slowly presses the drawing to her chest with teary eyes; Kachi tilts its head. Keep the miniature clay diorama look and every character design identical to the first frame. One simple, small action only; subtle, slow, gentle motion; the camera stays almost still with at most a slow gentle push-in. No text, no morphing faces, no extra fingers or limbs, no sudden camera shake, no cuts.", "dur": 5, "cap": "From her grandkid, far away.", "detail": "child's drawing of grandma + child + hearts"}], "details": [{"prop": "담 위 곡식 그릇(새 모이)", "where": [1], "meaning": "할머니가 늘 새들에게 모이를 줬다 = 까치가 이 집을 찾아온 이유"}, {"prop": "천 밑으로 삐져나온 까치 꽁지깃", "where": [1], "meaning": "정체를 눈치채는 재미"}, {"prop": "빈 그릇 → 곶감 하나", "where": [1, 2], "meaning": "줄 것 없는데도 내어 줌"}, {"prop": "아이 그림(할머니+아이+하트)", "where": [3], "meaning": "멀리 사는 손주의 소식 = 까치가 가져온 좋은 소식"}], "est_usd": 1.13, "notes": "P0 미달(이유·반전·까치 역할 없음)이라 새로 씀. 유령 꼬마의 정체가 까치, 사탕 대신 손주 그림 소포를 가져온다. 할머니 얼굴은 까치밥 편 kb2_point 를 ref 로. 새 그림 3장(유령→정체 공개는 변신이라 마지막 프레임 이어 쓰기 금지) ≈ $1.13. 그림에 글자 없음, 호박은 귀엽게.", "score": {"surprise": 5, "emotion": 4, "natural": 4, "kachi": 5}, "description": "Halloween night. Grandma had no candy left for the tiny ghost at her gate… but the ghost didn't come for candy.\n\nIn Korea, the magpie is the bird that brings good news 🐦\n\n#Halloween #Grandma #Magpie #Korea #Wholesome #shorts", "pinned": "Who would YOU want a surprise parcel from? 🎃 Tell Kachi 💛", "format": "season-halloween", "hook_type": "costume-reveal"}$j$::jsonb, outline = $j$[{"scene": "empty bowl; black tail feathers under the sheet; grain dish on the wall", "cap": "A tiny ghost. And no candy left.", "action": "The tiny ghost gives one small hop on the step and lifts its pumpkin basket; the grandma's face softens into a smile."}, {"scene": "sheet on the step, dried persimmon in the basket", "cap": "It came to give, not to take.", "action": "Kachi slowly pushes the heart parcel toward the grandma; she laughs softly."}, {"scene": "child's drawing of grandma + child + hearts", "cap": "From her grandkid, far away.", "action": "The grandma slowly presses the drawing to her chest with teary eyes; Kachi tilts its head."}]$j$::jsonb, feedback = coalesce(feedback,'[]'::jsonb) || $j$[{"at": "2026-10-28T08:50:00Z", "by": "claude", "type": "note", "text": "촬영표 완성(PLAN-FIRST): 3컷, 예상 $1.13. 점수 놀라움5·감정4·자연4·까치5. P0 미달(이유·반전·까치 역할 없음)이라 새로 씀. 유령 꼬마의 정체가 까치, 사탕 대신 손주 그림 소포를 가져온다. 할머니 얼굴은 까치밥 편 kb2_point 를 ref 로. 새 그림 3장(유령→정체 공개는 변신이라 마지막 프레임 이어 쓰기 금지) ≈ $1.13. 그림에 글자 없음,"}]$j$::jsonb, updated_at=now(), title = $j$The tiny ghost at Grandma's gate 🎃$j$, title_ko = $j$할머니 집 앞 꼬마 유령$j$, hook = $j$첫 프레임: 빈 그릇 든 할머니 앞, 천 밑으로 까치 꽁지깃이 삐져나온 꼬마 유령$j$, korea = $j$한옥 대문·곶감·새 모이 그릇$j$ where id='P261031-halloween-gotgam';